import {player,fatigue} from './engine.js';
import {canPlayPosition} from './player-positions.js';
export function recommendation(s){
 if(s.finished)return {title:'Find the decision that changed it.',text:'Rewind the match and compare a different tactical call from the same saved moment.',action:'nav',value:'explorer',label:'Explore this match',evidence:'Full-time · '+s.score.join(' : ')};
 const resolve=id=>s.rosters?.flat().concat(s.reserves?.flat()||[]).find(p=>p.id===id)||player(id);
 const starters=s.lineup.filter(id=>s.incidentVersion!==1||s.activeSlots[s.rosters[0].findIndex(p=>p.id===id)]).map(id=>({id,p:resolve(id),energy:s.fitness[id]})).sort((a,b)=>a.energy-b.energy);
 for(const tired of starters){const reserve=s.bench.map(resolve).filter(p=>p.role===tired.p.role&&(s.incidentVersion!==1||canPlayPosition(p,tired.p.assignedPosition))).sort((a,b)=>b.rating-a.rating)[0];if(tired.energy<68&&s.subs<5&&reserve)return {title:'Fresh legs for '+tired.p.name.split(' ').at(-1)+'.',text:`${Math.round(tired.energy)}% energy is limiting this position. ${reserve.name} is an eligible ${reserve.role} replacement. This uses one substitution.`,action:'coach-sub',out:tired.id,in:reserve.id,label:'Bring on '+reserve.name.split(' ').at(-1),evidence:(5-s.subs)+' substitutions left'};}
 const recent=s.events.filter(e=>e.minute>Math.max(0,s.minute-10)),lost=recent.filter(e=>e.type==='recovery'&&e.team===1&&e.x>25&&e.x<75&&e.y>18&&e.y<46);
 if(lost.length>=3&&(s.world||s.buildUps)&&s.buildUps?.[0]!=='short')return {title:'Give the midfield a shorter option.',text:'Three or more central losses in the last ten minutes. Shorter build-up limits passing distance and favors clear lanes; you may progress more slowly.',action:'coach-build',value:'short',label:'Use short build-up',evidence:lost.length+' central losses · last 10 minutes'};
 if(s.minute>=65&&s.score[0]>s.score[1]&&s.preset!=='protect')return {title:'Close the middle. Protect the lead.',text:'You lead with '+(90-s.minute)+' minutes left. A compact block reduces exposure, with less attacking commitment.',action:'tactic',value:'protect',label:'Protect the lead',evidence:s.score.join(' : ')+' · '+s.minute+'′'};
 if(s.preset==='press'&&fatigue(s)<77)return {title:'The press is costing you energy.',text:'Team energy is '+fatigue(s)+'%. Switch to a balanced approach to slow fatigue; you will give up some high recoveries.',action:'tactic',value:'balanced',label:'Ease the press',evidence:fatigue(s)+'% team energy'};
 if(s.minute>=20&&s.shots[0]===0&&(s.world||s.buildUps)&&s.buildUps?.[0]!=='direct'&&(s.preset==='press'||s.score[0]===s.score[1]))return {title:'Find an earlier forward pass.',text:'You have not attempted a shot yet. Direct build-up looks forward sooner and can help you reach the attacking third; longer passes are easier to lose.',action:'coach-build',value:'direct',label:'Try direct build-up',evidence:'No shots · '+s.minute+' minutes played'};
 if((s.score[0]<s.score[1]||s.shots[0]+2<s.shots[1])&&s.preset!=='press'&&fatigue(s)>70)return {title:'Win the next ball higher.',text:'You are '+(s.score[0]<s.score[1]?'chasing the score':'being outshot')+'. Press higher to raise recoveries and attacking commitment. It costs energy and leaves space behind.',action:'tactic',value:'press',label:'Raise the press',evidence:s.shots.join(' : ')+' shots · '+fatigue(s)+'% energy'};
 return {title:s.minute?'Hold your approach. Read the next phase.':'Set the tone before kick-off.',text:'Your shape is stable. Review positional cover on the bench; save your substitutions for tired players or a change in the score.',action:s.minute?'bench':'tactic',value:s.minute?null:s.preset==='balanced'?'press':'balanced',label:s.minute?'Review the bench':s.preset==='balanced'?'Try a higher press':'Choose balance',evidence:s.shots.join(' : ')+' shots · '+fatigue(s)+'% energy'};
}
